const root = "/home/diogenes/Projects/apps/twyne";
async function output(args: string[]): Promise<string> {
  const child = Bun.spawn(["rtk", "proxy", ...args], { cwd: root, stdout: "pipe", stderr: "pipe" });
  const [stdout, , code] = await Promise.all([new Response(child.stdout).text(), new Response(child.stderr).text(), child.exited]);
  if (code !== 0 || !stdout.trim()) throw new Error(`Credential/configuration read failed: ${args.slice(0, 3).join(" ")}`);
  return stdout.trim();
}
const mode = process.argv[2] ?? "wallet";
const env = { ...process.env };
await Promise.all(["NOTORGANIC_ISSUER", "NOTORGANIC_AUDIENCE", "NOTORGANIC_ASSERTION_PRIVATE_KEY"].map(async key => {
  env[key] = await output(["bunx", "convex", "env", "get", "--prod", key]);
}));
env.NOTORGANIC_ENABLED = "true";
env.TWYNE_EVAL_DID = await output(["skate", "get", "twyne-eval-did"]);
env.TWYNE_EVAL_SESSION_VERSION = "0";
env.TWYNE_EVAL_MAX_COST_MICROUSD = "200000";
env.NOTORGANIC_GENERATION_MAX_COST_MICROUSD = "200000";
env.ARIZE_SPACE_ID = "U3BhY2U6MjE5OkI1UjA=";
Object.assign(process.env, env);
const no = await import(`${root}/convex/lib/notorganic.ts`);
if (mode === "usage") {
  const token = await no.issueNotOrganicAccessToken({did: env.TWYNE_EVAL_DID, feature: "desk-usage", capabilities: ["usage:read"], sessionVersion: 0});
  const usage = await no.providerJsonRequest("/v1/usage?limit=100", token, {}, {issuer: no.notOrganicIssuer(), feature: "desk-usage"});
  const rows = (usage as any).data ?? [];
  console.log(JSON.stringify({rows: rows.length, states: Object.fromEntries([...new Set(rows.map((r:any)=>r.state))].map(s=>[s, rows.filter((r:any)=>r.state===s).length])), billed: rows.reduce((n:number,r:any)=>n+(r.billedMicros??0),0), reconciled: rows.filter((r:any)=>r.reconciliationReason).map((r:any)=>({model:r.model,billed:r.billedMicros,reason:r.reconciliationReason})), highest: rows.map((r:any)=>({model:r.model,billed:r.billedMicros,createdAt:r.createdAt})).sort((a:any,b:any)=>b.billed-a.billed).slice(0,5)}));
} else if (mode === "wallet") {
  const token = await no.issueNotOrganicAccessToken({did: env.TWYNE_EVAL_DID, feature: "wallet", capabilities: ["wallet:read"], sessionVersion: 0});
  const wallet = await no.providerJsonRequest("/v1/wallet", token, {}, {issuer: no.notOrganicIssuer(), feature: "wallet"});
  console.log(JSON.stringify(wallet));
} else {
  const direct = process.argv.includes("--direct");
  const keenable = process.argv.includes("--keenable");
  if (direct) env.TYPESAFE_API_KEY = await output(["skate", "get", "typesafe_api_key"]);
  if (keenable) env.KEENABLE_API_KEY = await output(["skate", "get", "keenable-api-key@secrets"]);
  Object.assign(process.env, env);
  if (mode === "probe" || mode === "jevprobe") {
    const {startLocalApp} = await import(`${root}/evals/app/local-app.ts`);
    const {TwyneClient} = await import(`${root}/packages/twyne-tools/src/client.ts`);
    const app = await startLocalApp({model: "notorganic", systemOne: direct ? "direct" : undefined, research: keenable ? "keenable" : "notorganic", env});
    try {
      console.log("transport", app.modelLabel);
      if (mode === "jevprobe") {
        const {JEV_NOTE_QUESTIONS} = await import(`${root}/evals/app/judges.ts`);
        const {roomSuite} = await import(`${root}/evals/app/suites/room.ts`);
        const c = roomSuite.load()[0];
        const results = await Promise.all(Array.from({length:5},(_,i)=>app.judge({state:{draft:c.draftText,note:`Note ${i}: the draft's argument needs a clearer warrant.`,anchor:c.plants[0].passage},questions:JEV_NOTE_QUESTIONS})));
        console.log("batch",JSON.stringify(results));
      } else {
      const j = await app.judge({state:{claim:"Apollo 11 landed on the Moon in 1969."},questions:{real:{type:"noul",instructions:"Does claim describe an event in the real world?"}}});
      console.log("judgement", JSON.stringify({ok:j.ok, transport:j.transport, error:j.error, answers:j.answers}));
      const e = await app.extract({state:"Apollo 11 landed on July 20, 1969.",fields:{year:{type:"number",instructions:"The year in which Apollo 11 landed."}}});
      console.log("extraction", JSON.stringify({ok:e.ok, transport:e.transport, error:e.error, answers:e.answers}));
      const writer = await app.newWriter("provider-probe");
      const client = new TwyneClient({apiUrl:app.url,accessToken:writer.token,fetch:app.fetch});
      try {
        const s = await client.request({operation:"research.sources",target:{kind:"event",anchor:"Apollo 11 landed on the Moon in 1969.",query:"NASA Apollo 11 landing July 20 1969"},maxResults:3});
        console.log("search", JSON.stringify(s));
      } catch(error) { console.log("search", error instanceof Error ? error.message : "failed"); }
      }
    } finally {await app.close();}
  } else if (mode === "run") {
    const {runAppEvals} = await import(`${root}/evals/app/run.ts`);
    const flag = (name:string) => {const i=process.argv.indexOf(name);return i<0?undefined:process.argv[i+1];};
    const reports=await runAppEvals({
      suites:(flag("--suite")??"room,rubric,rewrite,dossier,interview,research-targets,research-sources").split(",") as any,
      target:"local",model:"notorganic",systemOne:direct?"direct":undefined,research:keenable?"keenable":"notorganic",
      driver:"mcp",judge:process.argv.includes("--no-llm-judge")?"none":"notorganic",jev:true,
      ...(flag("--limit")?{limit:Number(flag("--limit"))}:{}),
      ...(flag("--case")?{caseIds:flag("--case")!.split(",")}:{}),
      concurrency:Number(flag("--concurrency")??1),arize:!process.argv.includes("--no-upload"),
      trace:false,project:"twyne-app-evals",experiment:flag("--experiment")??"scaled-20261023",out:`${root}/reports/app-evals`,env,
    });
    console.log("finished", JSON.stringify(reports.map(r=>({suite:r.suite,cases:r.cases.length,errors:r.errors,billed:r.billed,arize:r.arize}))));
    if(reports.some(r=>r.errors)) process.exitCode=1;
  } else throw new Error("Unknown mode");
}

