/**
 * The room of editors, convened on a draft through `twyne_convene_room`.
 *
 * Each case plants checkable features in a 550-900 word draft: unsupported
 * claims, weak arguments, bloat, a strong passage worth protecting. The
 * deterministic checks ask whether the room found them, whether each note
 * pinned itself to a passage the writer actually wrote, and whether five
 * editors read like five people. The judge, when enabled, applies the same
 * faithfulness and helpfulness rubrics as `evals/judge.ts` to every note.
 */
import {
  askJev,
  judged,
  judgeFaithfulness,
  judgeHelpfulness,
  judgeNoteValue,
  JEV_NOTE_QUESTIONS,
} from "../judges";
import {
  contains,
  distinctness,
  fold,
  mean,
  ratio,
  sharesRun,
  spansOverlap,
  visibleToEditors,
  type Score,
} from "../scoring";
import { readJsonl } from "./load";
import type { EditorNote, ProjectBrief, Suite } from "./types";

interface Plant {
  id: string;
  kind: string;
  passage: string;
  expectedEditors: string[];
  note: string;
}

export interface RoomCase {
  case_id: string;
  genre: string;
  brief: ProjectBrief;
  draftText: string;
  plants: Plant[];
}

function notesOf(raw: unknown): EditorNote[] {
  const notes = (raw as { notes?: unknown })?.notes;
  return Array.isArray(notes) ? (notes as EditorNote[]) : [];
}

/** Editors whose notes the app's editorial review would not release. */
function withheldOf(raw: unknown): string[] {
  const withheld = (raw as { withheld?: unknown })?.withheld;
  return Array.isArray(withheld) ? (withheld as string[]) : [];
}

function anchorsOf(note: EditorNote): string[] {
  if (note.anchors?.length) return note.anchors;
  return note.anchor ? [note.anchor] : [];
}

function covers(draft: string, note: EditorNote, plant: Plant): boolean {
  return (
    anchorsOf(note).some((anchor) =>
      spansOverlap(draft, anchor, plant.passage),
    ) || sharesRun(note.text, plant.passage, 5)
  );
}

export function renderNotes(notes: EditorNote[]): string {
  return notes
    .map((note) => {
      const head = `[${note.personaName ?? note.personaId}] (${note.type ?? "note"}, ${note.provider ?? "?"})`;
      const anchor = note.anchor ? `\n  > ${note.anchor}` : "";
      return `${head} ${note.text}${anchor}`;
    })
    .join("\n\n");
}

export const roomSuite: Suite<RoomCase> = {
  name: "room",
  surface: "MCP twyne_convene_room",
  load: () => readJsonl<RoomCase>("app/cases/room.jsonl"),

  async run({ mcp }, testCase) {
    const raw = await mcp.call("twyne_convene_room", {
      draftText: testCase.draftText,
      brief: testCase.brief,
    });
    return { raw, output: renderNotes(notesOf(raw)) };
  },

  async score({ judge, jev }, testCase, raw) {
    const draft = testCase.draftText;
    const notes = notesOf(raw);
    const written = notes.filter((note) => note.text?.trim());
    const anchors = notes.flatMap(anchorsOf);
    const verbatim = anchors.filter((anchor) => contains(draft, anchor));
    const visible = testCase.plants.filter((plant) =>
      visibleToEditors(draft, plant.passage),
    );
    const coveredBy = (plant: Plant) =>
      notes.filter((note) => covers(draft, note, plant));
    const missed = testCase.plants.filter((p) => coveredBy(p).length === 0);
    const expectedHit = testCase.plants.filter((plant) =>
      coveredBy(plant).some((note) =>
        plant.expectedEditors.includes(note.personaId),
      ),
    );
    const primary = notes
      .map((note) => note.anchor)
      .filter(Boolean) as string[];

    const scores: Record<string, Score> = {
      notes_complete: {
        score: ratio(written.length, 5),
        explanation:
          `${written.length} of 5 editors wrote a note` +
          (withheldOf(raw).length
            ? `; withheld by the editorial review: ${withheldOf(raw).join(", ")}`
            : ""),
      },
      hosted: {
        score:
          ratio(
            notes.filter((note) => note.provider && note.provider !== "local")
              .length,
            notes.length,
          ) ?? 0,
        explanation: `providers: ${[...new Set(notes.map((n) => n.provider))].join(", ")}`,
      },
      anchored: {
        score:
          ratio(notes.filter((note) => note.anchor).length, notes.length) ?? 0,
        explanation: "share of notes pinned to a passage by quote_passage",
      },
      anchor_verbatim: {
        // No anchors at all is a room that pinned nothing, not a missing check.
        score: ratio(verbatim.length, anchors.length) ?? 0,
        explanation: `${verbatim.length}/${anchors.length} anchors appear verbatim in the draft`,
      },
      plant_coverage: {
        score: ratio(
          testCase.plants.length - missed.length,
          testCase.plants.length,
        ),
        explanation: missed.length
          ? `missed: ${missed.map((p) => `${p.id} (${p.kind})`).join(", ")}`
          : "every planted feature was noticed",
      },
      plant_coverage_visible: {
        score:
          ratio(
            visible.filter((plant) => coveredBy(plant).length > 0).length,
            visible.length,
          ) ?? 1,
        explanation: `${testCase.plants.length - visible.length} plant(s) sit in the middle the editors' 4,500-character clamp drops`,
      },
      expected_editor: {
        score: ratio(expectedHit.length, testCase.plants.length),
        explanation:
          "planted features noticed by an editor whose remit covers them",
      },
      anchor_spread: {
        score: ratio(new Set(primary.map(fold)).size, primary.length) ?? 0,
        explanation: "distinct passages chosen across the room",
      },
      voice_distinctness: {
        score: distinctness(written.map((note) => note.text)) ?? 0,
        explanation: "1 minus mean pairwise trigram overlap between notes",
      },
    };

    if (judge) {
      const verdicts = await Promise.all(
        written.map(async (note) => ({
          note,
          faithful: await judgeFaithfulness(judge, draft, note.text),
          helpful: await judgeHelpfulness(
            judge,
            `${note.personaName ?? note.personaId} (${note.personaId})`,
            draft,
            note.text,
          ),
          value: await judgeNoteValue(judge, {
            draft,
            persona: `${note.personaName ?? note.personaId} (${note.personaId})`,
            note: note.text,
            anchor: note.anchor,
          }),
        })),
      ).then(
        (value) => ({ ok: true as const, value }),
        (error: unknown) => ({ ok: false as const, error }),
      );
      const perNote = (pick: "faithful" | "helpful" | "value"): Score =>
        verdicts.ok
          ? {
              score: verdicts.value.some((v) => v[pick].score === null)
                ? null
                : (mean(verdicts.value.map((v) => v[pick].score)) ?? 0),
              label: verdicts.value.some((v) => v[pick].score === null)
                ? "judge-error"
                : undefined,
              explanation:
                verdicts.value
                  .map((v) => `${v.note.personaId}: ${v[pick].label}`)
                  .join("; ") || "no notes to judge",
            }
          : {
              score: null,
              label: "judge-error",
              explanation:
                verdicts.error instanceof Error
                  ? verdicts.error.message
                  : String(verdicts.error),
            };
      scores.faithfulness = await judged(async () => perNote("faithful"));
      scores.helpfulness = await judged(async () => perNote("helpful"));
      // The discriminating one: anchored 1-5 levels, scaled to 0-1.
      scores.note_value = await judged(async () => perNote("value"));
    }
    if (jev && written.length) {
      // One batched Jev request per note, all notes in parallel.
      const perNote = await Promise.all(
        written.map((note) =>
          askJev(
            jev,
            {
              draft,
              note: note.text,
              anchor: note.anchor ?? "(no passage quoted)",
            },
            JEV_NOTE_QUESTIONS,
          ),
        ),
      );
      for (const key of Object.keys(JEV_NOTE_QUESTIONS)) {
        const values = perNote.map((answers) => answers[key]?.score ?? null);
        const failed = perNote.filter(
          (answers) => answers[key]?.label === "jev-error",
        ).length;
        scores[key] = {
          score: failed ? null : mean(values),
          label: failed ? "jev-error" : undefined,
          explanation: written
            .map(
              (note, i) =>
                `${note.personaId}: ${perNote[i][key]?.label ?? "?"}`,
            )
            .join("; "),
        };
      }
    }
    return scores;
  },

  example: (testCase) => ({
    case_id: testCase.case_id,
    genre: testCase.genre,
    draftText: testCase.draftText,
    brief: JSON.stringify(testCase.brief),
    plants: JSON.stringify(testCase.plants),
  }),
};
/**
 * The rubric, graded through `twyne_grade_draft` on strong/weak pairs.
 *
 * Each topic has a strong draft and a fluent but padded, hedging, generic
 * one under the same brief. The rubric earns its keep only if it ranks the
 * pair correctly, so ordering is scored per pair and attached to both cases.
 * The judge, when enabled, checks whether the feedback on a weak draft names
 * the weaknesses that were planted in it.
 *
 * With `--jev`, Jev reads every draft on the rubric's own four dimensions,
 * blind to the app's grades, as an independent check of the app's judges;
 * the four readings combine into `jev_quality` and a Jev pair order. On weak
 * drafts Jev also answers, weakness by weakness, the question the LLM judge
 * answers for `weakness_recall`.
 */
import {
  askJev,
  JEV_RUBRIC_QUESTIONS,
  jevComposite,
  jevRubricState,
  jevShare,
  jevWeaknessRequest,
  judged,
  judgeFaithfulness,
  judgeWeaknessRecall,
  type JevAsk,
} from "../judges";
import { pass, ratio, type Score } from "../scoring";
import { readJsonl } from "./load";
import type { ProjectBrief, ScoredCase, Suite } from "./types";

export interface RubricCase {
  case_id: string;
  pair_id: string;
  quality: "strong" | "weak";
  brief: ProjectBrief;
  draftText: string;
  weaknesses?: string[];
}

interface Judgement {
  score: number;
  rationale: string;
  provider?: string;
}

export interface RubricGrade {
  /** Persona judges that returned nothing usable, even after a retry. */
  unjudged?: string[];
  grade?: string;
  combined?: number;
  judgeMean?: number;
  minJudge?: number;
  staticTotal?: number;
  judges?: Array<Judgement & { personaId: string }>;
  sufficiency?: Judgement;
  evidence?: Judgement;
  integrity?: Judgement;
  targetFit?: Judgement;
  review?: { text: string; provider?: string } | null;
}

export const DIMENSIONS = [
  "sufficiency",
  "evidence",
  "integrity",
  "targetFit",
] as const;

/** The Jev question that reads each of the app's dimensions. */
export const JEV_DIMENSION: Record<
  (typeof DIMENSIONS)[number],
  keyof typeof JEV_RUBRIC_QUESTIONS
> = {
  sufficiency: "jev_sufficiency",
  evidence: "jev_evidence",
  integrity: "jev_integrity",
  targetFit: "jev_target_fit",
};

export function gradeOf(raw: unknown): RubricGrade {
  return (raw ?? {}) as RubricGrade;
}

function validJudgement(j: Judgement | undefined): boolean {
  return (
    !!j &&
    Number.isInteger(j.score) &&
    j.score >= 1 &&
    j.score <= 10 &&
    typeof j.rationale === "string" &&
    j.rationale.trim().length > 0
  );
}

function feedbackText(grade: RubricGrade): string {
  return [
    ...(grade.judges ?? []).map((j) => `${j.personaId}: ${j.rationale}`),
    ...DIMENSIONS.map((d) => `${d}: ${grade[d]?.rationale ?? ""}`),
    grade.review?.text ? `Review: ${grade.review.text}` : "",
  ]
    .filter(Boolean)
    .join("\n");
}

export function renderGrade(grade: RubricGrade): string {
  const judges = (grade.judges ?? [])
    .map((j) => `  ${j.personaId.padEnd(8)} ${j.score}  ${j.rationale}`)
    .join("\n");
  const dims = DIMENSIONS.map(
    (d) =>
      `  ${d.padEnd(11)} ${grade[d]?.score ?? "-"}  ${grade[d]?.rationale ?? ""}`,
  ).join("\n");
  return (
    `Grade ${grade.grade ?? "?"} (combined ${grade.combined ?? "?"}, judges ${grade.judgeMean ?? "?"}, static ${grade.staticTotal ?? "?"})\n` +
    `${judges}\n${dims}` +
    (grade.review?.text ? `\n\n${grade.review.text}` : "")
  );
}

/**
 * Jev's four blind readings, and their equal-weight composite. Equal weights
 * because the app's combined grade does not weight the dimensions either;
 * change them here if the composite should track something else.
 */
async function jevReadings(
  jev: JevAsk,
  testCase: RubricCase,
): Promise<Record<string, Score>> {
  const answers = await askJev(
    jev,
    jevRubricState(testCase.draftText, testCase.brief.answers),
    JEV_RUBRIC_QUESTIONS,
  );
  const scores: Record<string, Score> = {};
  for (const id of Object.keys(JEV_RUBRIC_QUESTIONS)) scores[id] = answers[id];
  scores.jev_quality = jevComposite(
    Object.keys(JEV_RUBRIC_QUESTIONS).map((id) => [answers[id], 1]),
  );
  return scores;
}

export const rubricSuite: Suite<RubricCase> = {
  name: "rubric",
  surface: "MCP twyne_grade_draft",
  load: () => readJsonl<RubricCase>("app/cases/rubric.jsonl"),

  async run({ mcp }, testCase) {
    const raw = await mcp.call("twyne_grade_draft", {
      draftText: testCase.draftText,
      brief: testCase.brief,
    });
    return { raw, output: renderGrade(gradeOf(raw)) };
  },

  async score({ judge, jev }, testCase, raw) {
    const grade = gradeOf(raw);
    const judges = grade.judges ?? [];
    const all: Array<Judgement | undefined> = [
      ...judges,
      ...DIMENSIONS.map((d) => grade[d]),
    ];
    const invalid = all.filter((j) => !validJudgement(j)).length;
    const scores: Record<string, Score> = {
      contract: pass(
        typeof grade.grade === "string" &&
          typeof grade.combined === "number" &&
          judges.length + (grade.unjudged?.length ?? 0) === 5 &&
          invalid === 0,
        invalid ? `${invalid} judgement(s) missing or out of range` : undefined,
      ),
      // Every editor actually read and scored the draft; a gap is reported
      // by the app rather than papered over with a heuristic.
      judged: {
        score: judges.length / 5,
        explanation: grade.unjudged?.length
          ? `unjudged: ${grade.unjudged.join(", ")}`
          : "all five editors scored the draft",
      },
      hosted: {
        score: ratio(
          all.filter((j) => j?.provider && j.provider !== "local").length,
          all.length,
        ),
        explanation:
          "judgements answered by the hosted model, not the local fallback",
      },
      review_present: pass(!!grade.review?.text?.trim()),
    };

    const weaknesses =
      testCase.quality === "weak" && testCase.weaknesses?.length
        ? testCase.weaknesses
        : null;
    // Jev's requests run alongside the judge's, not after them.
    const blind = jev ? jevReadings(jev, testCase) : null;
    const named =
      jev && weaknesses
        ? (async () => {
            const request = jevWeaknessRequest(feedbackText(grade), weaknesses);
            const answers = await askJev(jev, request.state, request.questions);
            return jevShare(answers, request.ids);
          })()
        : null;

    if (judge) {
      const review = grade.review?.text?.trim();
      scores.review_grounded = await judged(async () => {
        if (!review)
          return { score: 0, label: "absent", explanation: "no review" };
        const grounded = await judgeFaithfulness(
          judge,
          testCase.draftText,
          review,
        );
        return {
          score: grounded.score,
          label: grounded.score === null ? "judge-error" : grounded.label,
          explanation: grounded.explanation,
        };
      });
      if (weaknesses) {
        scores.weakness_recall = await judged(() =>
          judgeWeaknessRecall(judge, {
            draft: testCase.draftText,
            weaknesses,
            feedback: feedbackText(grade),
          }),
        );
      }
    }
    if (blind) Object.assign(scores, await blind);
    if (named) scores.jev_weakness_recall = await named;
    return scores;
  },

  scoreAll(results: Array<ScoredCase<RubricCase>>) {
    const pairs = new Map<
      string,
      Partial<Record<"strong" | "weak", ScoredCase<RubricCase>>>
    >();
    for (const result of results) {
      const pair = pairs.get(result.case.pair_id) ?? {};
      pair[result.case.quality] = result;
      pairs.set(result.case.pair_id, pair);
    }
    for (const { strong, weak } of pairs.values()) {
      if (!strong || !weak) continue;
      const a = gradeOf(strong.raw);
      const b = gradeOf(weak.raw);
      // One reading per pair, copied onto both drafts.
      const order = (x?: number | null, y?: number | null): Score =>
        typeof x === "number" && typeof y === "number"
          ? {
              score: x > y ? 1 : x === y ? 0.5 : 0,
              label: x > y ? "ordered" : x === y ? "tied" : "inverted",
              explanation: `strong ${Number(x.toFixed(3))} vs weak ${Number(y.toFixed(3))}`,
              sharedByCluster: true,
            }
          : {
              score: null,
              explanation: "a grade is missing",
              sharedByCluster: true,
            };
      const scores: Record<string, Score> = {
        pair_order: order(a.combined, b.combined),
        evidence_order: order(a.evidence?.score, b.evidence?.score),
        integrity_order: order(a.integrity?.score, b.integrity?.score),
        sufficiency_order: order(a.sufficiency?.score, b.sufficiency?.score),
      };
      if (strong.scores.jev_quality || weak.scores.jev_quality)
        scores.jev_pair_order = order(
          strong.scores.jev_quality?.score,
          weak.scores.jev_quality?.score,
        );
      Object.assign(strong.scores, scores);
      Object.assign(weak.scores, scores);
    }
  },

  example: (testCase) => ({
    case_id: testCase.case_id,
    pair_id: testCase.pair_id,
    quality: testCase.quality,
    draftText: testCase.draftText,
    brief: JSON.stringify(testCase.brief),
    weaknesses: JSON.stringify(testCase.weaknesses ?? []),
  }),
};

/**
 * Statistics for app eval reports: how much a suite mean can be trusted, and
 * whether a change between two runs is bigger than the noise.
 *
 *  - Every metric mean carries a 95% interval. Cases that share a draft or a
 *    strong/weak pair are not independent (a pair-order score is copied onto
 *    both cases of its pair), so the standard error is cluster-robust and the
 *    interval's degrees of freedom count clusters, not cases. The interval is
 *    Wilson's on an effective sample size, which stays inside 0..1 and stays
 *    honest at 10/10 or nine 1s and a 0.8 (see `summarizeValues`).
 *  - Two runs are compared case by case. The delta's interval is the same
 *    cluster-robust t interval; the p-value comes from an exact sign-flip test
 *    over clusters, which makes no normality assumption and cannot call three
 *    flipped cases significant. A change is flagged only when both agree.
 *  - Evaluators that measure the same thing (Jev, the LLM judge, a
 *    deterministic check) are compared on the cases where all of them scored.
 *  - Repeated runs of one suite split the noise into run-to-run variance and
 *    differences between cases.
 */
import type { Score } from "./scoring";

/** The parts of a report case these statistics read. */
export interface CaseLike {
  case_id: string;
  /** Cases that are not independent share a cluster (a pair, a draft). */
  cluster?: string;
  /** Case attributes worth slicing by (quality, strategy, level). */
  facets?: Record<string, string>;
  ok?: boolean;
  skipped?: boolean;
  scores: Record<string, Score>;
  raw?: unknown;
}

export interface MetricSummary {
  mean: number | null;
  /** Cases with a score. */
  n: number;
  /** 95% interval for the mean; null with fewer than two clusters. */
  ci?: [number, number] | null;
  /** Cluster-robust standard error of the mean. */
  se?: number | null;
  /** Standard deviation across cases. */
  sd?: number | null;
  /** Independent units behind the mean: cases, or pairs and drafts. */
  clusters?: number;
  /**
   * The number of independent pass/fail trials that would pin the mean down
   * as tightly as these cases do: more than n when each case averages several
   * readings (five notes, four weaknesses), fewer when cases are clustered.
   */
  effectiveN?: number | null;
  /** `wilson`: z critical value; `wilson-t`: t on clusters − 1 degrees of freedom. */
  method?: "wilson" | "wilson-t" | null;
}

export const Z95 = 1.959963984540054;

/** Two-sided 95% critical values of Student's t for 1-30 degrees of freedom. */
const T975 = [
  Number.NaN, 12.7062, 4.3027, 3.1824, 2.7764, 2.5706, 2.4469, 2.3646, 2.306, 2.2622,
  2.2281, 2.201, 2.1788, 2.1604, 2.1448, 2.1314, 2.1199, 2.1098, 2.1009, 2.093, 2.086,
  2.0796, 2.0739, 2.0687, 2.0639, 2.0595, 2.0555, 2.0518, 2.0484, 2.0452, 2.0423,
];

/** The 97.5th percentile of Student's t with `df` degrees of freedom. */
export function tCritical(df: number): number {
  if (!(df >= 1)) return Number.NaN;
  if (df <= 30 && Number.isInteger(df)) return T975[df];
  // Cornish-Fisher expansion; within 1e-4 of the exact value above 30.
  const z = Z95;
  return (
    z +
    (z ** 3 + z) / (4 * df) +
    (5 * z ** 5 + 16 * z ** 3 + 3 * z) / (96 * df ** 2) +
    (3 * z ** 7 + 19 * z ** 5 + 17 * z ** 3 - 15 * z) / (384 * df ** 3)
  );
}

/** Wilson score interval for a proportion `p` observed on `n` trials. */
export function wilson(p: number, n: number, z = Z95): [number, number] {
  if (!(n > 0)) return [0, 1];
  const z2 = z * z;
  const denominator = 1 + z2 / n;
  const center = (p + z2 / (2 * n)) / denominator;
  const half = (z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n))) / denominator;
  // At 0/n or n/n one end is exact; do not let rounding move it.
  return [p <= 0 ? 0 : Math.max(0, center - half), p >= 1 ? 1 : Math.min(1, center + half)];
}

function sum(values: number[]): number {
  return values.reduce((total, v) => total + v, 0);
}

function average(values: number[]): number {
  return sum(values) / values.length;
}

function sampleSd(values: number[]): number | null {
  if (values.length < 2) return null;
  const m = average(values);
  return Math.sqrt(sum(values.map((v) => (v - m) ** 2)) / (values.length - 1));
}

const clamp01 = (x: number) => Math.min(1, Math.max(0, x));

/**
 * Cluster-robust (CR1) standard error of a mean. With one case per cluster
 * it is the ordinary s/√n.
 */
export function clusterSe(
  values: number[],
  clusters: string[],
): { se: number | null; clusters: number } {
  const n = values.length;
  const totals = new Map<string, number>();
  if (n === 0) return { se: null, clusters: 0 };
  const m = average(values);
  values.forEach((v, i) => totals.set(clusters[i], (totals.get(clusters[i]) ?? 0) + (v - m)));
  const g = totals.size;
  if (g < 2) return { se: null, clusters: g };
  let squares = 0;
  for (const total of totals.values()) squares += total * total;
  return { se: Math.sqrt((g / (g - 1)) * squares) / n, clusters: g };
}

/**
 * Mean, spread and 95% interval of one metric over the cases that have it.
 *
 * Every score lives on 0..1 and many sit near an end (nine notes of ten
 * rated good), where a t interval on a handful of cases is far too narrow.
 * So the interval is Wilson's, on an effective sample size: the number of
 * pass/fail trials with the same variance of the mean, p(1 − p) / se², with
 * se cluster-robust (Korn and Graubard's interval for clustered proportions).
 * When the variance is estimated rather than implied by the mean, the
 * critical value is t on clusters − 1 degrees of freedom. Independent
 * pass/fail cases get the plain Wilson interval. When every value is the
 * same there is no design effect to estimate; count independent clusters.
 */
export function summarizeValues(
  points: Array<{ value: number | null | undefined; cluster: string }>,
): MetricSummary {
  const present = points.filter(
    (p): p is { value: number; cluster: string } =>
      typeof p.value === "number" && Number.isFinite(p.value),
  );
  const n = present.length;
  if (n === 0)
    return { mean: null, n: 0, ci: null, se: null, sd: null, clusters: 0, effectiveN: null, method: null };
  const values = present.map((p) => p.value);
  const mean = average(values);
  const sd = sampleSd(values);
  const { se, clusters } = clusterSe(
    values,
    present.map((p) => p.cluster),
  );
  if (clusters < 2 || se === null)
    return { mean, n, ci: null, se: null, sd, clusters, effectiveN: null, method: null };

  const p = clamp01(mean);
  const binary = values.every((v) => v === 0 || v === 1);
  // No variation cannot establish independence within a cluster. Use the
  // independent cluster count, invariant under within-cluster duplication.
  if (se === 0 || p * (1 - p) === 0)
    return { mean, n, ci: wilson(p, clusters), se, sd, clusters, effectiveN: clusters, method: "wilson" };
  if (binary && clusters === n)
    return { mean, n, ci: wilson(p, n), se, sd, clusters, effectiveN: n, method: "wilson" };
  const effectiveN = (p * (1 - p)) / (se * se);
  return {
    mean,
    n,
    ci: wilson(p, effectiveN, tCritical(clusters - 1)),
    se,
    sd,
    clusters,
    effectiveN,
    method: "wilson-t",
  };
}

/* ── Clusters and facets ─────────────────────────────────────────── */

/**
 * The cluster a case belongs to. Reports written since clusters were
 * recorded carry it; older ones are read from the case_id conventions:
 * research cases are `<draft>:<claim or strategy>`, rubric cases end in
 * `-strong` or `-weak`.
 */
export function clusterOf(suite: string, c: CaseLike): string {
  if (c.cluster) return c.cluster;
  if (suite.startsWith("research") && c.case_id.includes(":"))
    return c.case_id.slice(0, c.case_id.indexOf(":"));
  if (suite === "rubric") return c.case_id.replace(/-(strong|weak)$/, "");
  return c.case_id;
}

/** A case attribute, with the same fallback for reports that predate facets. */
export function facetOf(suite: string, c: CaseLike, name: string): string | undefined {
  const recorded = c.facets?.[name];
  if (recorded !== undefined) return recorded;
  if (suite === "rubric" && name === "quality")
    return c.case_id.match(/-(strong|weak)$/)?.[1];
  if (suite === "research-targets" && name === "strategy")
    return c.case_id.match(/:(hosted|model)$/)?.[1];
  return undefined;
}

/** Quality is conditional on execution; harness measures execution itself. */
export function metricValue(c: Pick<CaseLike, "ok" | "scores">, name: string): number | null {
  if (name === "harness") {
    const value = c.scores.harness?.score;
    if (typeof value === "number" && Number.isFinite(value)) return value;
    return c.ok === undefined ? null : c.ok ? 1 : 0;
  }
  if (c.ok === false) return null;
  const value = c.scores[name]?.score;
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function scored(c: CaseLike): boolean {
  return !c.skipped;
}

/**
 * Is this metric copied across each cluster rather than measured per case?
 * Older rubric reports did not mark their pair orderings, so those are
 * recognised by name.
 */
export function sharedMetric(suite: string, name: string, cases: CaseLike[]): boolean {
  return (
    cases.some((c) => c.scores[name]?.sharedByCluster) ||
    (suite === "rubric" && /_order$/.test(name))
  );
}

/** Every metric in a suite's cases, with a cluster-aware interval. */
export function summarizeCases(
  suite: string,
  cases: CaseLike[],
): Record<string, MetricSummary> {
  const live = cases.filter(scored);
  const names = [...new Set(live.flatMap((c) => Object.keys(c.scores)))];
  return Object.fromEntries(
    names.map((name) => {
      let points = live.map((c) => ({ value: metricValue(c, name), cluster: clusterOf(suite, c) }));
      if (sharedMetric(suite, name, live)) {
        const seen = new Set<string>();
        points = points.filter((p) => {
          if (typeof p.value !== "number" || seen.has(p.cluster)) return false;
          seen.add(p.cluster);
          return true;
        });
      }
      return [name, summarizeValues(points)];
    }),
  );
}

/**
 * The same summary for each value of a facet, when the cases carry two or
 * more values of it: research-targets' two strategies are two systems, and
 * their pooled mean describes neither.
 */
export function summarizeByFacet(
  suite: string,
  cases: CaseLike[],
  facet: string,
): Record<string, Record<string, MetricSummary>> | null {
  const values = [...new Set(cases.map((c) => facetOf(suite, c, facet)).filter((v): v is string => !!v))];
  if (values.length < 2) return null;
  return Object.fromEntries(
    values.sort().map((value) => [
      value,
      summarizeCases(
        suite,
        cases.filter((c) => facetOf(suite, c, facet) === value),
      ),
    ]),
  );
}

/* ── Paired comparison of two runs ───────────────────────────────── */

/** A seeded PRNG, so a Monte Carlo p-value is the same on every run. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Two-sided sign-flip (permutation) test that the paired differences are
 * centred on zero. `totals` holds one summed difference per cluster. Exact up
 * to 16 non-zero clusters, Monte Carlo beyond.
 */
export function signFlipP(totals: number[], draws = 20_000): number {
  const nonzero = totals.filter((d) => Math.abs(d) > 1e-12);
  const k = nonzero.length;
  if (k === 0) return 1;
  const observed = Math.abs(sum(nonzero)) - 1e-9;
  let extreme = 0;
  if (k <= 16) {
    const all = 1 << k;
    for (let mask = 0; mask < all; mask++) {
      let s = 0;
      for (let j = 0; j < k; j++) s += mask & (1 << j) ? -nonzero[j] : nonzero[j];
      if (Math.abs(s) >= observed) extreme++;
    }
    return extreme / all;
  }
  const random = mulberry32(0x7779e);
  for (let r = 0; r < draws; r++) {
    let s = 0;
    for (const d of nonzero) s += random() < 0.5 ? -d : d;
    if (Math.abs(s) >= observed) extreme++;
  }
  return (extreme + 1) / (draws + 1);
}

/** Benjamini-Hochberg adjusted p-values (q), nulls left in place. */
export function benjaminiHochberg(ps: Array<number | null>): Array<number | null> {
  const ranked = ps
    .map((p, i) => ({ p, i }))
    .filter((x): x is { p: number; i: number } => typeof x.p === "number")
    .sort((a, b) => a.p - b.p);
  const q: Array<number | null> = ps.map(() => null);
  let running = 1;
  for (let r = ranked.length - 1; r >= 0; r--) {
    running = Math.min(running, (ranked[r].p * ranked.length) / (r + 1));
    q[ranked[r].i] = running;
  }
  return q;
}

export interface MetricDelta {
  metric: string;
  /** Cases scored in both runs. */
  n: number;
  clusters: number;
  /** Means over the paired cases only. */
  base: number | null;
  next: number | null;
  delta: number | null;
  ci: [number, number] | null;
  /** Sign-flip test over clusters. */
  p: number | null;
  /** Benjamini-Hochberg across the metrics of this comparison. */
  q: number | null;
  /** Up or down beyond noise: the CI excludes zero and p < 0.05. */
  flag: "up" | "down" | null;
}

export interface Comparison {
  suite: string;
  base: string;
  next: string;
  /** Cases present in only one run are left out of every delta. */
  pairedCases: number;
  onlyBase: number;
  onlyNext: number;
  metrics: MetricDelta[];
}

export function comparePaired(
  suite: string,
  baseCases: CaseLike[],
  nextCases: CaseLike[],
  labels: { base: string; next: string } = { base: "baseline", next: "this run" },
): Comparison {
  const base = new Map(baseCases.filter(scored).map((c) => [c.case_id, c]));
  const next = new Map(nextCases.filter(scored).map((c) => [c.case_id, c]));
  const shared = [...next.keys()].filter((id) => base.has(id));
  const names = [
    ...new Set(
      shared.flatMap((id) => Object.keys(next.get(id)!.scores)).filter((name) =>
        shared.some((id) => base.get(id)!.scores[name] !== undefined),
      ),
    ),
  ];
  const metrics: MetricDelta[] = names.map((metric) => {
    const rows = shared.flatMap((id) => {
      const a = metricValue(base.get(id)!, metric);
      const b = metricValue(next.get(id)!, metric);
      return typeof a === "number" && typeof b === "number"
        ? [{ a, b, cluster: clusterOf(suite, next.get(id)!) }]
        : [];
    });
    if (!rows.length)
      return { metric, n: 0, clusters: 0, base: null, next: null, delta: null, ci: null, p: null, q: null, flag: null };
    const deltas = rows.map((r) => r.b - r.a);
    const clusters = rows.map((r) => r.cluster);
    const delta = average(deltas);
    const { se, clusters: g } = clusterSe(deltas, clusters);
    const totals = new Map<string, number>();
    rows.forEach((r, i) => totals.set(r.cluster, (totals.get(r.cluster) ?? 0) + deltas[i]));
    const p = signFlipP([...totals.values()]);
    // Scores live on 0..1, so no difference can leave −1..1.
    const ci: [number, number] | null =
      se === null
        ? null
        : [Math.max(-1, delta - tCritical(g - 1) * se), Math.min(1, delta + tCritical(g - 1) * se)];
    const beyond = ci !== null && p < 0.05 && (ci[0] > 0 || ci[1] < 0);
    return {
      metric,
      n: rows.length,
      clusters: g,
      base: average(rows.map((r) => r.a)),
      next: average(rows.map((r) => r.b)),
      delta,
      ci,
      p,
      q: null,
      flag: beyond ? (delta > 0 ? "up" : "down") : null,
    };
  });
  const q = benjaminiHochberg(metrics.map((m) => m.p));
  metrics.forEach((m, i) => (m.q = q[i]));
  return {
    suite,
    base: labels.base,
    next: labels.next,
    pairedCases: shared.length,
    onlyBase: [...base.keys()].filter((id) => !next.has(id)).length,
    onlyNext: [...next.keys()].filter((id) => !base.has(id)).length,
    metrics,
  };
}

/* ── Agreement between evaluators ────────────────────────────────── */

export function pearson(x: number[], y: number[]): number | null {
  const n = x.length;
  if (n < 3) return null;
  const mx = average(x);
  const my = average(y);
  let sxy = 0;
  let sxx = 0;
  let syy = 0;
  for (let i = 0; i < n; i++) {
    sxy += (x[i] - mx) * (y[i] - my);
    sxx += (x[i] - mx) ** 2;
    syy += (y[i] - my) ** 2;
  }
  return sxx > 0 && syy > 0 ? sxy / Math.sqrt(sxx * syy) : null;
}

function ranks(values: number[]): number[] {
  const order = values.map((v, i) => ({ v, i })).sort((a, b) => a.v - b.v);
  const out = new Array<number>(values.length);
  for (let i = 0; i < order.length; ) {
    let j = i;
    while (j + 1 < order.length && order[j + 1].v === order[i].v) j++;
    for (let k = i; k <= j; k++) out[order[k].i] = (i + j) / 2 + 1;
    i = j + 1;
  }
  return out;
}

export function spearman(x: number[], y: number[]): number | null {
  return pearson(ranks(x), ranks(y));
}

/** Fisher-z 95% interval for a correlation. */
export function correlationCi(r: number | null, n: number): [number, number] | null {
  if (r === null || n <= 3 || Math.abs(r) >= 1) return null;
  const z = Math.atanh(r);
  const half = Z95 / Math.sqrt(n - 3);
  return [Math.tanh(z - half), Math.tanh(z + half)];
}

/** Cohen's kappa after reading each value as pass (>= 0.5) or fail. */
export function kappa(x: number[], y: number[]): { agree: number | null; kappa: number | null } {
  const n = x.length;
  if (!n) return { agree: null, kappa: null };
  const a = x.map((v) => v >= 0.5);
  const b = y.map((v) => v >= 0.5);
  const agree = a.filter((v, i) => v === b[i]).length / n;
  const pa = a.filter(Boolean).length / n;
  const pb = b.filter(Boolean).length / n;
  const chance = pa * pb + (1 - pa) * (1 - pb);
  return { agree, kappa: chance < 1 ? (agree - chance) / (1 - chance) : null };
}

export interface AgreementPair {
  a: string;
  b: string;
  n: number;
  pearson: number | null;
  pearsonCi: [number, number] | null;
  spearman: number | null;
  /** Share of cases both evaluators put on the same side of 0.5. */
  agree: number | null;
  kappa: number | null;
  /** Mean of a − b: which evaluator reads higher. */
  meanDiff: number | null;
}

export function agreementPair(a: string, b: string, x: number[], y: number[]): AgreementPair {
  const r = pearson(x, y);
  const { agree, kappa: k } = kappa(x, y);
  return {
    a,
    b,
    n: x.length,
    pearson: r,
    pearsonCi: correlationCi(r, x.length),
    spearman: spearman(x, y),
    agree,
    kappa: k,
    meanDiff: x.length ? average(x.map((v, i) => v - y[i])) : null,
  };
}

/**
 * How well a reading separates known-good from known-bad cases: the chance a
 * random good case outscores a random bad one (ties count half).
 */
export function auc(good: number[], bad: number[]): number | null {
  if (!good.length || !bad.length) return null;
  let wins = 0;
  for (const g of good) for (const b of bad) wins += g > b ? 1 : g === b ? 0.5 : 0;
  return wins / (good.length * bad.length);
}

/* ── Repeatability across repeated runs ──────────────────────────── */

export interface Repeatability {
  metric: string;
  runs: number;
  /** Cases scored in every run. */
  cases: number;
  runMeans: number[];
  /** Standard deviation of the suite mean from run to run. */
  sdOfRunMeans: number | null;
  /** Pooled standard deviation of one case's score across runs. */
  withinCaseSd: number | null;
  /** What run-to-run noise alone does to a suite mean: withinCaseSd / √cases. */
  noiseSe: number | null;
  /** ICC(1): the share of score variance due to real differences between cases. */
  icc: number | null;
}

export function repeatability(runs: CaseLike[][]): Repeatability[] {
  const k = runs.length;
  if (k < 2) return [];
  const byId = runs.map((cases) => new Map(cases.filter(scored).map((c) => [c.case_id, c])));
  const names = [...new Set(runs.flatMap((cases) => cases.flatMap((c) => Object.keys(c.scores))))];
  return names.map((metric) => {
    const ids = [...byId[0].keys()].filter((id) =>
      byId.every((m) => m.has(id) && metricValue(m.get(id)!, metric) !== null),
    );
    const grid = ids.map((id) => byId.map((m) => metricValue(m.get(id)!, metric) as number));
    const n = grid.length;
    const runMeans = byId.map((_, r) => (n ? average(grid.map((row) => row[r])) : Number.NaN));
    if (n < 2)
      return { metric, runs: k, cases: n, runMeans, sdOfRunMeans: null, withinCaseSd: null, noiseSe: null, icc: null };
    const caseMeans = grid.map(average);
    const grand = average(caseMeans);
    const msw = sum(grid.map((row, i) => sum(row.map((v) => (v - caseMeans[i]) ** 2)))) / (n * (k - 1));
    const msb = (k * sum(caseMeans.map((m) => (m - grand) ** 2))) / (n - 1);
    const denominator = msb + (k - 1) * msw;
    return {
      metric,
      runs: k,
      cases: n,
      runMeans,
      sdOfRunMeans: sampleSd(runMeans),
      withinCaseSd: Math.sqrt(msw),
      noiseSe: Math.sqrt(msw / n),
      icc: denominator > 0 ? (msb - msw) / denominator : null,
    };
  });
}

/* ── Formatting ──────────────────────────────────────────────────── */

const fixed = (x: number | null | undefined, digits = 2) =>
  typeof x === "number" && Number.isFinite(x) ? x.toFixed(digits) : "-";
const signed = (x: number | null | undefined, digits = 2) =>
  typeof x === "number" && Number.isFinite(x) ? `${x >= 0 ? "+" : "−"}${Math.abs(x).toFixed(digits)}` : "-";

export function formatInterval(ci: [number, number] | null | undefined, sign = false): string {
  if (!ci) return "";
  const f = sign ? signed : fixed;
  return `[${f(ci[0])}, ${f(ci[1])}]`;
}

/** One printed line per metric: mean, 95% interval, cases and clusters. */
export function formatSummaryLines(summary: Record<string, MetricSummary>): string[] {
  return Object.entries(summary).map(([name, s]) => {
    const mean = s.mean === null ? "   -" : s.mean.toFixed(2);
    const ci = formatInterval(s.ci).padEnd(14);
    const units =
      s.clusters !== undefined && s.clusters < s.n
        ? `n=${s.n}, ${s.clusters} cluster${s.clusters === 1 ? "" : "s"}`
        : `n=${s.n}`;
    return `  ${name.padEnd(24)} ${mean}  ${ci} (${units})`;
  });
}

export function formatComparison(comparison: Comparison): string[] {
  const lines = [
    `  vs ${comparison.base}: ${comparison.pairedCases} case(s) paired by case_id` +
      (comparison.onlyBase || comparison.onlyNext
        ? ` (${comparison.onlyBase} only in the baseline, ${comparison.onlyNext} only here)`
        : ""),
    `    ${"metric".padEnd(24)} ${"base".padStart(5)} ${"now".padStart(5)} ${"Δ".padStart(6)}  ${"95% CI".padEnd(16)} ${"p".padStart(5)}`,
  ];
  if (comparison.metrics.some((m) => m.n > 0 && m.clusters < 5))
    lines.push("    (fewer than five clusters paired: intervals are too wide to call any change)");
  for (const m of comparison.metrics) {
    const mark = m.flag === "up" ? "▲" : m.flag === "down" ? "▼" : "";
    lines.push(
      `    ${m.metric.padEnd(24)} ${fixed(m.base).padStart(5)} ${fixed(m.next).padStart(5)} ${signed(m.delta).padStart(6)}  ${formatInterval(m.ci, true).padEnd(16)} ${fixed(m.p).padStart(5)} ${mark}`.trimEnd(),
    );
  }
  const moved = comparison.metrics.filter((m) => m.flag);
  const survive = moved.filter((m) => (m.q ?? 1) < 0.05);
  lines.push(
    `    ${moved.length} of ${comparison.metrics.length} metric(s) moved beyond noise (CI excludes 0 and sign-flip p < 0.05)` +
      (moved.length ? `; ${survive.length} survive Benjamini-Hochberg at q < 0.05` : ""),
  );
  return lines;
}

export function formatRepeatability(rows: Repeatability[]): string[] {
  if (!rows.length) return [];
  const lines = [
    `  run-to-run variance over ${rows[0].runs} runs`,
    `    ${"metric".padEnd(24)} ${"run means".padEnd(22)} ${"sd(mean)".padStart(8)} ${"case sd".padStart(8)} ${"noise se".padStart(8)} ${"icc".padStart(5)}`,
  ];
  for (const r of rows)
    lines.push(
      `    ${r.metric.padEnd(24)} ${r.runMeans.map((m) => fixed(m)).join(" ").padEnd(22)} ${fixed(r.sdOfRunMeans, 3).padStart(8)} ${fixed(r.withinCaseSd, 3).padStart(8)} ${fixed(r.noiseSe, 3).padStart(8)} ${fixed(r.icc).padStart(5)}`,
    );
  return lines;
}

