const root = "/home/diogenes/Projects/apps/twyne";
async function output(args: string[]): Promise<string> {
  const child = Bun.spawn(["rtk", "proxy", ...args], { cwd: root, stdout: "pipe", stderr: "pipe" });
  const [stdout, , code] = await Promise.all([new Response(child.stdout).text(), new Response(child.stderr).text(), child.exited]);
  if (code !== 0 || !stdout.trim()) throw new Error(`Credential/configuration read failed: ${args.slice(0, 3).join(" ")}`);
  return stdout.trim();
}
const mode = process.argv[2] ?? "wallet";
const env = { ...process.env };
await Promise.all(["NOTORGANIC_ISSUER", "NOTORGANIC_AUDIENCE", "NOTORGANIC_ASSERTION_PRIVATE_KEY"].map(async key => {
  env[key] = await output(["bunx", "convex", "env", "get", "--prod", key]);
}));
env.NOTORGANIC_ENABLED = "true";
env.TWYNE_EVAL_DID = await output(["skate", "get", "twyne-eval-did"]);
env.TWYNE_EVAL_SESSION_VERSION = "0";
env.TWYNE_EVAL_MAX_COST_MICROUSD = "200000";
env.NOTORGANIC_GENERATION_MAX_COST_MICROUSD = "200000";
env.ARIZE_SPACE_ID = "U3BhY2U6MjE5OkI1UjA=";
Object.assign(process.env, env);
const {readFileSync,writeFileSync}=await import('node:fs');
const {runAppEvals}=await import(`${root}/evals/app/run.ts`);
const {roomSuite}=await import(`${root}/evals/app/suites/room.ts`);
const {rubricSuite}=await import(`${root}/evals/app/suites/rubric.ts`);
const {rewriteSuite}=await import(`${root}/evals/app/suites/rewrite.ts`);
const {dossierSuite}=await import(`${root}/evals/app/suites/dossier.ts`);
const {interviewSuite}=await import(`${root}/evals/app/suites/interview.ts`);
const {researchTargetsSuite,researchSourcesSuite}=await import(`${root}/evals/app/suites/research.ts`);
const all=[roomSuite,rubricSuite,rewriteSuite,dossierSuite,interviewSuite,researchTargetsSuite,researchSourcesSuite];
const folder=`${root}/reports/app-evals`;
const options={suites:['room'],target:'local',model:'notorganic',research:'notorganic',driver:'mcp',judge:'notorganic',jev:true,concurrency:2,arize:false,trace:false,project:'twyne-app-evals',experiment:'scaled-verified-20261023',out:folder,env};
const requestEvidence:any[]=[];const nativeFetch=globalThis.fetch;let observationWrite=Promise.resolve();
globalThis.fetch=(async(input:any,init:any)=>{
 const url=new URL(typeof input==='string'?input:input instanceof URL?input.href:input.url);
 if(/\/extraction(?:$|\/)/.test(url.pathname))throw Error('CLAIRIC_DEFERRED_NO_EXTRACTION_CALLS');
 const response=await nativeFetch(input,init);
 if(url.hostname==='api.notorganic.info' && response.status>=400){
  requestEvidence.push({at:new Date().toISOString(),path:url.pathname,status:response.status,retryAfter:response.headers.get('retry-after')});
  observationWrite=observationWrite.then(async()=>{await Bun.write('/tmp/twyne-final-response-failures.json',JSON.stringify(requestEvidence,null,2));});await observationWrite;
 }
 return response;
}) as typeof fetch;
let coreFailures=0;
for(const suite of all){const score=suite.score;const run=suite.run;
 suite.run=async(ctx:any,c:any)=>{if(coreFailures>=3)throw Error('provider unavailable: recovery stopped after repeated core failures');try{return await run(ctx,c);}catch(e){coreFailures++;throw e;}};
 suite.score=async(ctx:any,c:any,raw:any)=>{const result=await score({...ctx,extract:null},c,raw);if(Object.values(result).some((s:any)=>s.label==='judge-error'))coreFailures++;else coreFailures=0;
  const deferred=suite.name==='dossier'?['length_claims']:suite.name==='interview'?['clairic_field_recall','clairic_field_support']:[];
  for(const key of deferred)result[key]={score:null,label:'deferred',explanation:'Clairic replay deferred after upstream 429; saved actor retained.'};return result;};
}
console.log('VALIDATION_START room-travel-advisory-market');
const validation=await runAppEvals({...options,caseIds:['room-travel-advisory-market'],experiment:'recovery-validation-20261023'} as any);
const validated=validation[0].cases[0];
const required=['hosted','faithfulness','helpfulness','note_value','jev_grounded','jev_note_value'];
if(!validated?.ok||required.some(k=>typeof validated.scores[k]?.score!=='number')||validated.scores.hosted.score!==1){console.log('VALIDATION_FAILED',JSON.stringify(validated?.scores));process.exit(2);}
console.log('VALIDATION_PASSED',JSON.stringify({case_id:validated.case_id,scores:validated.scores}));
const original=readFileSync(`${folder}/scaled-verified-20261023-room.pre-recovery.cases.jsonl`,'utf8').trim().split('\n').map((s:string)=>JSON.parse(s));
const cache=new Map<string,Map<string,any>>();
const roomCache=new Map<string,any>();for(const row of original){const prior=roomCache.get(row.case_id)??{};roomCache.set(row.case_id,{...prior,...row});}
// Scored actor failures have raw:null; only successful generated outputs are reusable.
for(const row of original.filter((r:any)=>r.phase==='generated')){const prior=roomCache.get(row.case_id);if(prior)roomCache.set(row.case_id,{...prior,raw:row.raw,output:row.output,latencyMs:row.latencyMs,traceId:row.traceId});}
roomCache.set(validated.case_id,validated);cache.set('room',roomCache);
for(const name of ['research-targets','research-sources']){const report=JSON.parse(readFileSync(`${folder}/outage-independent-20261023-${name}.json`,'utf8'));cache.set(name,new Map(report.cases.map((c:any)=>[c.case_id,c])));}
for(const suite of [roomSuite,researchTargetsSuite,researchSourcesSuite]){
 const originalRun=suite.run, originalScore=suite.score;const saved=cache.get(suite.name)!;
 suite.run=async(ctx:any,c:any)=>{const row=saved.get(c.case_id);if(row?.raw)return {raw:row.raw,output:row.output};return originalRun(ctx,c);};
 suite.score=async(ctx:any,c:any,raw:any)=>{
  const row=saved.get(c.case_id);if(!row?.ok)return originalScore(ctx,c,raw);
  if(suite.name==='research-sources'){
   const repaired=await originalScore({...ctx,jev:null,extract:null},c,raw);return {...row.scores,settles:repaired.settles};
  }
  const failed=Object.entries(row.scores).filter(([k,v]:any)=>/error/.test(v.label??''));
  if(!failed.length)return row.scores;
  if(failed.some(([k,v]:any)=>v.label!=='judge-error'))throw Error('Unexpected saved score failure');
  const repaired=await originalScore({...ctx,jev:null,extract:null},c,raw);return {...row.scores,...Object.fromEntries(failed.map(([k])=>[k,repaired[k]]))};
 };
}
const reports=await runAppEvals({...options,suites:all.map(s=>s.name)} as any);
for(const r of reports){const saved=cache.get(r.suite);if(saved){for(const c of r.cases){const previous=saved.get(c.case_id);if(previous?.raw){if(JSON.stringify(c.raw)!==JSON.stringify(previous.raw)||c.output!==previous.output)throw Error(`Saved actor changed ${c.case_id}`);c.latencyMs=previous.latencyMs;c.traceId=previous.traceId;c.actorProvenance='reused';}}r.recoveryStartedAt=r.startedAt;if(r.suite==='room'){r.startedAt='2026-10-23T21:38:48Z';r.startedAtBasis='Original process launch, second precision; exact in-memory suite start not persisted';}r.accountingNote='This process billing/usage excludes prior saved actor/scorer requests; use complete ledger with original run bound and probe exclusions.';writeFileSync(`${folder}/${r.experiment}.json`,JSON.stringify(r,null,2));}}
console.log('RESUMED_REPORTS_COMPLETE',JSON.stringify(reports.map(r=>({suite:r.suite,cases:r.cases.length,errors:r.errors,coverage:r.coverage}))));

