  const labelOnly = names.filter((name) => runs.some((run) => metricValue(run, name) === null));
  const metadataKeys = [...new Set(runs.flatMap((run) => Object.keys(run.metadata)))];
  const rows = runs.map((run) => {
    const row: Record<string, unknown> = {
      example_id: run.example_id,
